export default async function Page() {
  const reponse = await fetch("https://example.com/catalogue.json", { cache: "no-store" });
  if (!reponse.ok) throw new Error(`HTTP ${reponse.status}`);
  const livres = await reponse.json();
  return <pre>{JSON.stringify(livres, null, 2)}</pre>;
}
